import {topics} from './data.js';
import {esc,publicPage,banner,photo,link} from './ui.js';

const articles=[
 {source:['Арктический совет: биоразнообразие Арктики','https://oaarchive.arctic-council.org/bitstreams/ef0c5c94-a937-444e-a976-19abba31c965/download'],sections:[
 ['Где начинается Арктика','Граница Арктики зависит от задачи исследования. Географы используют полярный круг, а экологи учитывают климат и границу распространения деревьев. Поэтому на разных картах северный регион может выглядеть по-разному.'],
 ['Океан и суша','Арктика объединяет океан, острова и северные территории материков. Морские и наземные экосистемы связаны, но их нельзя описать одной характеристикой.'],
 ['Как читать карту','Проверяй легенду и определение границы в источнике. Сравни две карты: по полярному кругу и по природным зонам. Отметь, где различия сильнее всего.'],
 ['Идея исследования','Создай интерактивную карту определений Арктики. Объясни, для каких задач подходит каждая граница, и подпиши источники. Это предложение темы школьного проекта.']]},
 {source:['Норвежский полярный институт: белый медведь','https://npolar.no/en/species/polar-bear/'],sections:[
 ['Общая информация','Белый медведь — арктический хищник, жизнь которого тесно связана с морским льдом. Густой мех и слой жира помогают сохранять тепло.'],
 ['Среда обитания','Морской лёд нужен медведю для охоты и перемещений. У разных популяций условия различаются: где-то лёд сохраняется дольше, а где-то летом животные проводят время на суше.'],
 ['Питание','Основу рациона составляют тюлени. Медведь ищет добычу у полыней и трещин во льду, используя ледяную поверхность как площадку для охоты.'],
 ['Идея исследования','Сравни сезонные карты льда с описанием условий жизни одной популяции. Не переноси выводы для отдельного района на всю Арктику. Это предложение темы школьного проекта.']]},
 {source:['Росзаповедцентр: наблюдения на Медвежьих островах','https://iacgov.ru/press-center/news/1132/'],sections:[
 ['Заповедная территория','Медвежьи острова — охраняемая арктическая территория. Здесь изучают белых медведей и их местообитания, чтобы получать данные для сохранения природы.'],
 ['Как наблюдают за животными','В заповеднике проводили визуальные наблюдения и мультиспектральную авиасъёмку. Снимки позволяют исследовать животных и среду их обитания без приближения к каждому отдельному медведю.'],
 ['Люди и техника','Результат полевых наблюдений зависит от работы исследователей и экипажа. Сложная погода и удалённость территории требуют совместной подготовки.'],
 ['Идея исследования','Сравни ручной подсчёт объектов на учебных снимках с автоматическим распознаванием. Запиши ошибки обоих методов. Используй разрешённые изображения и не публикуй точные координаты уязвимых животных.']]},
 {source:['NSIDC: почему морской лёд важен','https://nsidc.org/learn/parts-cryosphere/sea-ice/why-sea-ice-matters'],sections:[
 ['Морской лёд и ледники','Морской лёд образуется при замерзании морской воды. Ледники формируются на суше из снега; эти процессы и их последствия различаются.'],
 ['Отражение света','Светлая ледяная поверхность отражает значительную часть солнечного света. Открытая тёмная вода поглощает больше энергии, поэтому изменения льда связаны с обменом теплом.'],
 ['Сезонный ритм','Лёд растёт в холодный сезон и тает в тёплый. Чтобы оценить изменение, сравнивай одинаковые месяцы разных лет, а не зиму одного года с летом другого.'],
 ['Идея исследования','Построй график площади морского льда для одного месяца по открытым данным. Укажи единицы, период и источник; отдели наблюдаемый тренд от своих предположений.']]},
 {source:['PAME: судоходство в Арктике','https://www.pame.is/ourwork/arctic-shipping/'],sections:[
 ['Северные морские маршруты','Северный морской путь относится к маршрутам вдоль северных берегов Евразии. Арктическое судоходство включает разные виды перевозок и разные направления.'],
 ['Лёд и планирование','При планировании рейса учитывают ледовую обстановку, сезон, возможности судна и доступную инфраструктуру. Наличие маршрута на карте само по себе не показывает, насколько легко по нему пройти.'],
 ['Воздействие на море','PAME изучает арктическое судоходство и вопросы защиты морской среды. Для оценки важны данные о движении судов и условиях конкретного района.'],
 ['Идея исследования','Сравни два возможных маршрута на учебной карте. Сделай таблицу факторов: расстояние, сезонность, инфраструктура и экологические вопросы. Не называй один маршрут лучшим без выбранных критериев.']]},
 {source:['British Antarctic Survey: карьера в полярной науке','https://www.bas.ac.uk/jobs/careers-at-bas/science/'],sections:[
 ['Команда полярного исследования','Полярные исследования объединяют разные специальности. Учёные изучают климат, океан и живые организмы, а инженеры и специалисты по данным помогают получать и обрабатывать наблюдения.'],
 ['Работа с данными','Результаты экспедиции продолжают изучать после возвращения. Анализ, проверка методов и сравнение измерений так же важны, как сбор материала.'],
 ['Какие навыки развивать','Полезны математика, естественные науки, программирование и умение работать в команде. BAS описывает междисциплинарную работу в обоих полярных регионах; условия конкретных вакансий различаются.'],
 ['Идея исследования','Выбери одну полярную профессию и составь карту навыков. Свяжи каждое умение с небольшой школьной задачей: обработкой таблицы, наблюдением или работой с картой.']]},
 {source:['Арктический совет: программа борьбы с загрязнением ACAP','https://www.arcticcouncil.org/about/working-groups/acap/'],sections:[
 ['Загрязнение и совместная работа','ACAP поддерживает действия по сокращению загрязняющих веществ и связанных рисков. Проблемы Арктики требуют сотрудничества исследователей, местных сообществ и организаций.'],
 ['От знания к действию','Сначала нужно определить источник проблемы и собрать данные. Затем можно предложить конкретную меру и проверить, меняется ли наблюдаемый результат.'],
 ['Школьный вклад','Выбери доступную локальную задачу: учёт отходов, ответственное потребление или проверку качества экологической информации. Объясни связь проекта с северными экосистемами без обещания решить все проблемы сразу.'],
 ['Идея исследования','Проведи аудит одноразовых материалов в школе за неделю. Предложи изменение и повтори измерение. Опиши ограничения: небольшой период, сезон и число участников.']]}
];

export function articlePage(params) {
 const requested=params.get('topic'),index=requested===null?1:Number(requested),n=Number.isInteger(index)&&articles[index]?index:1,a=articles[n],topic=topics[n],next=(n+1)%articles.length;
 return publicPage('bear',banner(topic[0],esc(topic[1]),{landscape:n!==1})+`<div class="container article-layout"><aside class="article-toc"><h3>Содержание</h3>${a.sections.map(([title],i)=>`<a href="#article-${i}" data-action="scroll-section" data-target="article-${i}">${i+1}. ${esc(title)}</a>`).join('')}</aside><article class="article-text">${a.sections.map(([title,text],i)=>`<section id="article-${i}"><h3><span class="mint-text">0${i+1}</span>　${esc(title)}</h3><p>${esc(text)}</p></section>`).join('')}<div class="card tinted"><h3>Источник</h3><a class="text-link" href="${a.source[1]}" target="_blank" rel="noopener">${esc(a.source[0])} ↗</a><p><small>Изображение — иллюстрация темы. Идея проекта предложена для самостоятельного исследования.</small></p></div></article><aside class="article-aside">${photo(topic[2],topic[0])}<div class="card"><h3>Следующая тема</h3>${link('bear?topic='+next,esc(topics[next][0])+' →','text-link')}</div></aside></div>`);
}
